const now = $now.setZone('America/Toronto');
const weekAgo = now.minus({ days: 7 }); const d28 = now.minus({ days: 28 });
const toDT = v => { if (!v) return null; const d = new Date(v); return isNaN(d.getTime()) ? null : DateTime.fromJSDate(d); };
const isTest = r => String(r.kind || '').toLowerCase() === 'test' || /^TEST\b/.test(String(r.business_name || ''));
const all = $('Load leads').all().map(i => i.json).filter(r => r && r.id);
const leads = all.filter(r => !isTest(r));
const events = $('Load events').all().map(i => i.json).filter(e => e && e.event && !/^TEST/.test(String(e.detail || '')));
const pct = (a, b) => b ? Math.round(100 * a / b) + '% (' + a + '/' + b + ')' : 'n/a (0 sent)';
const small = n => n < 20 ? ' [only ' + n + ', too few to judge]' : '';
const by = (rows, key) => { const o = {}; for (const r of rows) { const k = String(r[key] || 'unknown'); o[k] = (o[k] || 0) + 1; } return o; };
const statusCounts = by(leads, 'status');
const sentAll = leads.filter(r => r.sent_at);
const sentWeek = sentAll.filter(r => toDT(r.sent_at) >= weekAgo);
const cohort = sentAll.filter(r => toDT(r.sent_at) >= d28);
const replied = r => !!r.reply_class && r.reply_class !== 'OUT_OF_OFFICE' && r.reply_class !== 'BOUNCED';
const positive = r => ['POSITIVE_INTEREST','MEETING_REQUEST','PRICING_QUESTION'].includes(r.reply_class);
const seg = key => { const o = {}; for (const r of cohort) { const k = String(r[key] || 'unknown'); o[k] = o[k] || { sent: 0, replies: 0, positive: 0 }; o[k].sent++; if (replied(r)) o[k].replies++; if (positive(r)) o[k].positive++; } return Object.entries(o).map(([k, v]) => k + ': ' + v.sent + ' sent, reply ' + pct(v.replies, v.sent) + ', positive ' + pct(v.positive, v.sent) + small(v.sent)); };
const scored = leads.filter(r => typeof r.quality_score === 'number');
const avg = scored.length ? Math.round(scored.reduce((a, r) => a + r.quality_score, 0) / scored.length) : null;
const evWeek = events.filter(e => toDT(e.at) >= weekAgo);
const evCounts = by(evWeek, 'event');
const failures = evWeek.filter(e => /fail|error|bounce/i.test(String(e.event) + ' ' + String(e.detail || '')));
const m = {
  week: weekAgo.toISODate() + ' to ' + now.toISODate(),
  leads_total: leads.length, leads_by_status: statusCounts,
  first_emails_sent_this_week: sentWeek.length, first_emails_sent_all_time: sentAll.length,
  cohort_28_days_sent: cohort.length,
  reply_rate_28d: pct(cohort.filter(replied).length, cohort.length) + small(cohort.length),
  positive_rate_28d: pct(cohort.filter(positive).length, cohort.length) + small(cohort.length),
  bounce_rate_28d: pct(cohort.filter(r => r.status === 'BOUNCED' || r.reply_class === 'BOUNCED').length, cohort.length),
  unsubscribe_rate_28d: pct(cohort.filter(r => r.reply_class === 'UNSUBSCRIBE').length, cohort.length),
  replies_by_class_all_time: by(leads.filter(r => r.reply_class), 'reply_class'),
  meetings: leads.filter(r => r.meeting_status).length, customers: leads.filter(r => r.status === 'CUSTOMER' || r.customer_status).length,
  revenue_total: leads.reduce((a, r) => a + (parseFloat(r.revenue) || 0), 0),
  followups_done: leads.reduce((a, r) => a + (parseInt(r.followup_count || 0, 10)), 0),
  waiting_for_your_review: leads.filter(r => r.status === 'NEEDS_REVIEW').length,
  ai_decisions: by(leads.filter(r => r.ai_decision), 'ai_decision'), avg_quality_score: avg,
  by_industry_28d: seg('category'), by_campaign_28d: seg('campaign_id'),
  workflow_events_this_week: evCounts, failures_this_week: failures.length,
  failure_examples: failures.slice(0, 5).map(e => e.workflow + ': ' + e.event + ' ' + String(e.detail || '').slice(0, 120))
};
const fmt = v => Array.isArray(v) ? (v.length ? '\n' + v.map(x => '  - ' + x).join('\n') : 'none') : (v && typeof v === 'object') ? (Object.keys(v).length ? Object.entries(v).map(([k, x]) => k + ' ' + x).join(', ') : 'none') : String(v);
const text = Object.entries(m).map(([k, v]) => k.replace(/_/g, ' ') + ': ' + fmt(v)).join('\n').replace(/[{}]/g, '');
return [{ json: { metrics: m, metrics_text: text } }];

const m = $('Compute metrics').first().json;
const ai = ($json || {}).output;
const lines = ['FlowPilot weekly report, ' + m.metrics.week, '', 'NUMBERS (test rows excluded; rates use leads first emailed in the last 28 days as the denominator)', m.metrics_text, '', 'SUGGESTIONS (AI, based only on the numbers above; nothing changes unless you approve it)'];
if (ai && Array.isArray(ai.recommendations) && ai.recommendations.length) { for (const r of ai.recommendations) lines.push('- ' + String(r.suggestion || '') + ' | Why: ' + String(r.evidence || '') + ' | Confidence: ' + String(r.confidence || '')); if (ai.data_warning) lines.push('Data note: ' + ai.data_warning); }
else lines.push('AI suggestions unavailable this week (check the AI credits in n8n). The numbers above are complete.');
lines.push('', 'Nothing was changed automatically. Offers, sending volume and campaigns only change when you decide.');
return [{ json: { subject: 'FlowPilot weekly report ' + m.metrics.week, body: lines.join('\n') } }];
